/**
 * Sample data for the choropleth explorer: annual recurring revenue, growth and penetration for every US state, with
 * county detail for the ten states that have a field team.
 *
 * Shapes are derived from the US Census Bureau cartographic boundaries (us-atlas, public domain), projected to Albers USA
 * in a 975 by 610 view box and simplified. State paths are in view box units. County paths are drawn in a local
 * 1000 unit grid over their state and placed with `origin` ([x, y, unit]), which keeps them sharp when the map zooms in.
 * Values are illustrative.
 */

export type ChoroplethScale = "sequential" | "diverging";
export type ChoroplethFormat = "currency" | "change" | "percent";

export interface ChoroplethMetric {
  id: string;
  /** Label in the metric switch. */
  label: string;
  /** Label beside the headline total, in sentence case. */
  totalLabel: string;
  format: ChoroplethFormat;
  /** Symbol in front of currency values. Defaults to "$". */
  currency?: string;
  /** Sequential shades one hue from low to high; diverging splits at zero with a second hue for negative values. */
  scale: ChoroplethScale;
  /** How the headline combines regions: a plain sum, or an average weighted by the first metric. */
  aggregate: "sum" | "weighted";
}

export interface ChoroplethRegion {
  id: string;
  name: string;
  /** SVG path data. States use view box units; subregions use their parent's local grid. */
  path: string;
  /** Bounding box in view box units, [x, y, width, height]. Used to zoom. */
  box?: [number, number, number, number];
  /** One value per metric id. Null means no data (no accounts yet). */
  values: Record<string, number | null>;
  subregions?: ChoroplethSubregions;
}

export interface ChoroplethSubregions {
  /** Plural noun for the subregions, such as "counties". */
  noun: string;
  /** Places the local grid on the map: [x, y, view box units per local unit]. */
  origin: [number, number, number];
  regions: ChoroplethRegion[];
}

/** One area the explorer can show, such as a country. */
export interface ChoroplethMap {
  id: string;
  /** Name of the whole area, shown above the map before zooming in and in the area switch. */
  name: string;
  regions: ChoroplethRegion[];
  /** Plural noun for top level regions, such as "states". */
  regionNoun: string;
  /** Heading while this area is shown. */
  title?: string;
  /** Metrics for this area, such as the same metrics in a local currency. Defaults to the explorer's metrics. */
  metrics?: ChoroplethMetric[];
  /** Width and height of the view box the region paths are drawn in. Defaults to [975, 610]. */
  viewBox?: [number, number];
}

export const choroplethViewBox: [number, number] = [975, 610];

/** The three sample metrics, with revenue in the given currency symbol. */
export const choroplethLocalMetrics = (currency = "$"): ChoroplethMetric[] => [
  { id: "revenue", label: "Revenue", totalLabel: "Annual recurring revenue", format: "currency", currency, scale: "sequential", aggregate: "sum" },
  { id: "growth", label: "Growth", totalLabel: "Growth year over year", format: "change", scale: "diverging", aggregate: "weighted" },
  { id: "penetration", label: "Penetration", totalLabel: "Target accounts won", format: "percent", scale: "sequential", aggregate: "weighted" },
];

export const choroplethMetrics: ChoroplethMetric[] = choroplethLocalMetrics();

export const choroplethCaption = "Twelve months to August 31, 2026";

type SubRow = [id: string, name: string, revenue: number, growth: number | null, penetration: number | null, path: string];
/** Compact sample rows: a region with its values and path, and optionally the origin and rows of its subregions. Boxes are measured from the paths. */
export type ChoroplethRow =
  | [id: string, name: string, revenue: number, growth: number, penetration: number, path: string]
  | [id: string, name: string, revenue: number, growth: number, penetration: number, path: string, origin: [number, number, number], subregions: SubRow[]];

const subregion = ([id, name, revenue, growth, penetration, path]: SubRow): ChoroplethRegion => ({
  id, name, path, values: { revenue: revenue > 0 ? revenue : null, growth, penetration },
});

export function choroplethRegionsFromRows(rows: ChoroplethRow[], subregionNoun = "areas"): ChoroplethRegion[] {
  return rows.map(row => {
    const [id, name, revenue, growth, penetration, path] = row;
    const region: ChoroplethRegion = { id, name, path, values: { revenue, growth, penetration } };
    if (row.length === 8) region.subregions = { noun: subregionNoun, origin: row[6], regions: row[7].map(subregion) };
    return region;
  });
}

type CountyRow = [id: string, name: string, revenue: number, growth: number | null, penetration: number | null, path: string];
type StateRow =
  | [id: string, name: string, box: [number, number, number, number], revenue: number, growth: number, penetration: number, path: string]
  | [id: string, name: string, box: [number, number, number, number], revenue: number, growth: number, penetration: number, path: string, origin: [number, number, number], counties: CountyRow[]];

