const county = ([id, name, revenue, growth, penetration, path]: CountyRow): ChoroplethRegion => ({
  id, name, path, values: { revenue: revenue > 0 ? revenue : null, growth, penetration },
});

/** Every state and the District of Columbia, alphabetical by postal code. */
export const choroplethRegions: ChoroplethRegion[] = STATES.map(row => {
  const [id, name, box, revenue, growth, penetration, path] = row;
  const region: ChoroplethRegion = { id, name, path, box, values: { revenue, growth, penetration } };
  if (row.length === 9) region.subregions = { noun: "counties", origin: row[7], regions: row[8].map(county) };
  return region;
});

export const unitedStatesMap: ChoroplethMap = {
  id: "us",
  name: "United States",
  regionNoun: "states",
  title: "Revenue by state",
  metrics: choroplethMetrics,
  regions: choroplethRegions,
};
